import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'content-store',
  description:
    "Read and update the content studio: the long-form pieces (pieces.json) and the editorial calendar of what each piece spins off (calendar.json). action:'status' for the whole picture; 'add_piece' to save a piece (an existing title is updated, never duplicated); 'update_piece' to move a piece to another stage, reassign it or change its publish date; 'repurpose_piece' to plan a piece's newsletter, social posts or video chapters (count is how many of that format in all; only the missing ones are added, each dated after the piece); 'update_spinoff' to move or reschedule one of those; 'list' for everything.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'status', 'add_piece', 'update_piece', 'repurpose_piece', 'update_spinoff', or 'list'.",
      required: true,
    },
    id: { type: 'string', description: "A piece id ('pc-3'), or for update_spinoff a spin-off id ('so-2')." },
    title: {
      type: 'string',
      description: "The piece's title, e.g. 'How we price brand projects'. Also finds a piece (or a spin-off) when no id is given.",
    },
    format: {
      type: 'string',
      description:
        'For a piece: article, guide, case-study, interview, essay, video, podcast, or other. For repurpose_piece: newsletter, social-post, video-chapters, short-video, quote-card, or other.',
    },
    status: {
      type: 'string',
      description:
        'A piece stage (idea, brief, draft, edit, design, published), or for a spin-off: planned, drafted, scheduled, published.',
    },
    assignee: { type: 'string', description: 'Who is writing or making it.' },
    publishAt: { type: 'string', description: 'The day it publishes or goes out, YYYY-MM-DD.' },
    shiftDays: {
      type: 'number',
      description: 'Move the date by this many days (7 = a week later, -2 = two days earlier). The studio does the date math.',
    },
    keyword: { type: 'string', description: 'The search phrase the piece targets.' },
    angle: {
      type: 'string',
      description: "One line on what it says. For several spin-offs at once, separate one line each with ' | '.",
    },
    words: { type: 'number', description: 'Target length in words.' },
    link: { type: 'string', description: 'Where it was published.' },
    note: { type: 'string', description: 'What happened, in the person’s words.' },
    count: {
      type: 'number',
      description: 'For repurpose_piece: how many of this format the piece should have in all (three posts = 3). Only the missing ones are added.',
    },
    startAt: { type: 'string', description: 'For repurpose_piece: the day the first new one goes out, YYYY-MM-DD (default: after the piece publishes).' },
    channel: { type: 'string', description: "Where a spin-off goes out, e.g. 'LinkedIn', 'Instagram', 'YouTube', 'the newsletter'." },
    withinDays: { type: 'number', description: 'How many days ahead counts as publishing soon (default 14).' },
  },
  outputs: {
    inPipeline: { type: 'number', description: 'Pieces not yet published.' },
    dueSoon: { type: 'number', description: 'Pieces and spin-offs going out within the window.' },
    late: { type: 'number', description: 'Pieces and spin-offs past their date and not published.' },
    repurposed: { type: 'number', description: 'Published pieces with at least one spin-off.' },
    summary: { type: 'string', description: 'What changed, then the studio picture; or the listing.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── content-rules-start ──
// Pure derivations: local calendar days, spin-off dates after a piece
// publishes, record lookup by id or name, and the studio picture the crew
// reads. Kept self-contained between these sentinels so tests execute the
// shipped bytes.
var DAY_MS = 86400000;
var STAGES = ['idea', 'brief', 'draft', 'edit', 'design', 'published'];
var FORMATS = ['article', 'guide', 'case-study', 'interview', 'essay', 'video', 'podcast', 'other'];
var SPIN_FORMATS = ['newsletter', 'social-post', 'video-chapters', 'short-video', 'quote-card', 'other'];
var SPIN_STAGES = ['planned', 'drafted', 'scheduled', 'published'];
var SPIN_ALIASES = {
  post: 'social-post', posts: 'social-post', social: 'social-post', 'social post': 'social-post', 'social posts': 'social-post',
  'social-posts': 'social-post', 'linkedin post': 'social-post', thread: 'social-post', email: 'newsletter', newsletters: 'newsletter',
  'newsletter issue': 'newsletter', chapters: 'video-chapters', 'video chapters': 'video-chapters', 'youtube chapters': 'video-chapters',
  reel: 'short-video', reels: 'short-video', short: 'short-video', shorts: 'short-video', clip: 'short-video', 'short video': 'short-video',
  quote: 'quote-card', quotes: 'quote-card', 'quote card': 'quote-card', 'quote cards': 'quote-card',
};
var SPIN_NOUN = {
  newsletter: ['newsletter', 'newsletters'],
  'social-post': ['social post', 'social posts'],
  'video-chapters': ['set of video chapters', 'sets of video chapters'],
  'short-video': ['short video', 'short videos'],
  'quote-card': ['quote card', 'quote cards'],
  other: ['spin-off', 'spin-offs'],
};
var SPIN_LABEL = {
  newsletter: 'Newsletter', 'social-post': 'Social post', 'video-chapters': 'Video chapters', 'short-video': 'Short video',
  'quote-card': 'Quote card', other: 'Spin-off',
};
// Days after the piece publishes that the first of each format goes out; later ones follow every SPACING days.
var OFFSET = { newsletter: 3, 'social-post': 1, 'video-chapters': 7, 'short-video': 4, 'quote-card': 2, other: 7 };
var SPACING = 2;
var WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
var MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
var STOP = ['the', 'and', 'our', 'for', 'with', 'from', 'this', 'that', 'post', 'piece', 'article'];

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}
function localDay(ms) {
  var d = new Date(ms);
  return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
}
function addDays(day, n) {
  var d = new Date(String(day).slice(0, 10) + 'T12:00:00');
  d.setDate(d.getDate() + n);
  return localDay(d.getTime());
}
function daysLeft(day, nowMs) {
  var due = Date.parse(String(day).slice(0, 10) + 'T00:00:00');
  var today = Date.parse(localDay(nowMs) + 'T00:00:00');
  return Math.round((due - today) / DAY_MS);
}
// YYYY-MM-DD, or today/tomorrow, or a weekday ('friday' is the next one).
function normalizeDate(text, nowMs) {
  var raw = String(text || '').trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
  var lower = raw.toLowerCase();
  var today = localDay(nowMs);
  if (lower === 'today') return today;
  if (lower === 'tomorrow') return addDays(today, 1);
  var m = lower.match(/^(next |this )?(sunday|monday|tuesday|wednesday|thursday|friday|saturday)$/);
  if (m) {
    var target = WEEKDAYS.map(function (w) { return w.toLowerCase(); }).indexOf(m[2]);
    var dow = new Date(today + 'T12:00:00').getDay();
    return addDays(today, ((target - dow + 6) % 7) + 1);
  }
  var parsed = Date.parse(raw);
  if (!isFinite(parsed)) return null;
  if (/\d{4}/.test(raw)) return localDay(parsed);
  // 'Nov 20' parses into some default year: take this year's, or next year's once it is well past.
  var d = new Date(parsed);
  var year = new Date(nowMs).getFullYear();
  var guess = year + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
  return daysLeft(guess, nowMs) < -60 ? year + 1 + guess.slice(4) : guess;
}
function niceDay(day) {
  var d = new Date(String(day).slice(0, 10) + 'T12:00:00');
  return WEEKDAYS[d.getDay()].slice(0, 3) + ' ' + MONTHS[d.getMonth()] + ' ' + d.getDate();
}
function when(days) {
  if (days < 0) return -days + (days === -1 ? ' day late' : ' days late');
  if (days === 0) return 'today';
  return 'in ' + days + (days === 1 ? ' day' : ' days');
}
function wholeNumber(value) {
  var n = typeof value === 'string' ? Number(String(value).replace(/,/g, '')) : value;
  return typeof n === 'number' && isFinite(n) && n >= 0 ? Math.round(n) : null;
}
function spinFormat(text) {
  var key = String(text || '').trim().toLowerCase();
  if (!key) return null;
  if (SPIN_FORMATS.indexOf(key) >= 0) return key;
  return SPIN_ALIASES[key] || null;
}
function stem(word) {
  return word.replace(/(ing|ed|es|s|e)$/, '');
}
function words(text) {
  return (String(text || '').toLowerCase().match(/[a-z0-9]+/g) || []).map(stem).filter(function (w) {
    return w.length > 2 && STOP.indexOf(w) < 0;
  });
}
// The record a person means: its id, its exact title, a unique part of its
// title, or the title sharing the most words with what they wrote.
function findRecord(records, key) {
  var text = String(key || '').trim();
  if (!text) return { record: null, matches: [] };
  var lower = text.toLowerCase();
  var titleOf = function (r) { return String((r.fields && r.fields.title) || '').toLowerCase(); };
  var byId = records.filter(function (r) { return String(r.id).toLowerCase() === lower; });
  if (byId.length) return { record: byId[0], matches: byId };
  var exact = records.filter(function (r) { return titleOf(r) === lower; });
  if (exact.length === 1) return { record: exact[0], matches: exact };
  var partial = records.filter(function (r) { return titleOf(r).indexOf(lower) >= 0; });
  if (partial.length === 1) return { record: partial[0], matches: partial };
  if (partial.length > 1) return { record: null, matches: partial };
  var want = words(text);
  var best = 0;
  var hits = [];
  records.forEach(function (r) {
    var have = words(titleOf(r));
    var score = want.filter(function (w) { return have.indexOf(w) >= 0; }).length;
    if (score > best) { best = score; hits = [r]; } else if (score === best && score > 0) hits.push(r);
  });
  return { record: hits.length === 1 ? hits[0] : null, matches: hits };
}
// The dates for the spin-offs a piece still needs: after it publishes (or from today), one every SPACING days.
function spinoffDates(piece, format, already, missing, startAt, nowMs) {
  var today = localDay(nowMs);
  var f = piece.fields || {};
  var published = piece.status === 'published';
  var base = f.publishAt && !published && f.publishAt >= today ? f.publishAt : today;
  var first = startAt || addDays(base, (OFFSET[format] || 7) + already * SPACING);
  var out = [];
  for (var i = 0; i < missing; i++) out.push(addDays(first, i * SPACING));
  return out;
}
function spinoffTitle(format, index, total, pieceTitle) {
  return SPIN_LABEL[format] + (total > 1 || index > 0 ? ' ' + (index + 1) : '') + ': ' + pieceTitle;
}
function dateOf(r) {
  var f = r.fields || {};
  return r.status === 'published' ? f.publishedAt || f.publishAt || '' : f.publishAt || '';
}
function pieceLine(r, nowMs) {
  var f = r.fields || {};
  var d = dateOf(r);
  return (
    f.title + ' (' + r.id + ', ' + (f.format || 'article') + ', ' + (r.status === 'published' ? 'published' : 'in ' + r.status) +
    ', ' + (f.assignee || 'unassigned') + ')' + (d ? ' ' + niceDay(d) + (r.status === 'published' ? '' : ', ' + when(daysLeft(d, nowMs))) : ', no date yet')
  );
}
function spinoffLine(s, pieces, nowMs) {
  var f = s.fields || {};
  var piece = pieces.find(function (p) { return p.id === f.pieceId; });
  return (
    f.title + ' (' + s.id + ', ' + f.format + ' for ' + (piece ? piece.id : 'a removed piece') + ', ' + s.status +
    (f.channel ? ', ' + f.channel : '') + (f.assignee ? ', ' + f.assignee : '') + ')' +
    (f.publishAt ? ' ' + niceDay(f.publishAt) + (s.status === 'published' ? '' : ', ' + when(daysLeft(f.publishAt, nowMs))) : ', no date yet')
  );
}
function spinoffSummary(list) {
  return SPIN_FORMATS.map(function (format) {
    var mine = list.filter(function (s) { return s.fields.format === format; });
    if (!mine.length) return '';
    var byStage = SPIN_STAGES.map(function (st) {
      var n = mine.filter(function (s) { return s.status === st; }).length;
      return n ? (mine.length === 1 ? st : n + ' ' + st) : '';
    }).filter(Boolean).join(', ');
    return mine.length === 1 ? SPIN_NOUN[format][0] + ' ' + byStage : mine.length + ' ' + SPIN_NOUN[format][1] + ' (' + byStage + ')';
  }).filter(Boolean).join(', ');
}
function studioPicture(pieces, spinoffs, nowMs, withinDays) {
  var parts = [];
  var open = pieces.filter(function (p) { return p.status !== 'published'; });
  var stageCounts = STAGES.map(function (s) {
    var n = pieces.filter(function (p) { return p.status === s; }).length;
    return n ? n + ' ' + s : '';
  }).filter(Boolean);
  parts.push(pieces.length ? 'Pipeline: ' + pieces.length + (pieces.length === 1 ? ' piece' : ' pieces') + ' (' + stageCounts.join(', ') + ').' : 'No pieces yet.');
  var items = [];
  open.forEach(function (p) { if (p.fields.publishAt) items.push({ day: p.fields.publishAt, line: pieceLine(p, nowMs) }); });
  spinoffs.forEach(function (s) {
    if (s.status !== 'published' && s.fields.publishAt) items.push({ day: s.fields.publishAt, line: spinoffLine(s, pieces, nowMs) });
  });
  items.sort(function (a, b) { return a.day.localeCompare(b.day); });
  var late = items.filter(function (i) { return daysLeft(i.day, nowMs) < 0; });
  var soon = items.filter(function (i) { var d = daysLeft(i.day, nowMs); return d >= 0 && d <= withinDays; });
  var later = items.filter(function (i) { return daysLeft(i.day, nowMs) > withinDays; });
  // One list, late items first: asked what is publishing soon, a model must see what slipped.
  var due = late.concat(soon);
  parts.push(
    due.length
      ? 'Publishing in the next ' + withinDays + ' days, late items first: ' + due.map(function (i) { return i.line; }).join(' | ') + '.'
      : 'Nothing publishing in the next ' + withinDays + ' days.',
  );
  if (later.length) parts.push('Next after that: ' + later[0].line + '.');
  var undated = open.filter(function (p) { return !p.fields.publishAt; });
  if (undated.length) parts.push('No publish date yet: ' + undated.map(function (p) { return p.fields.title + ' (' + p.id + ', ' + p.status + ')'; }).join(', ') + '.');
  var people = {};
  var unassigned = [];
  open.forEach(function (p) {
    var who = p.fields.assignee;
    var entry = p.fields.title + ' (' + p.id + ', ' + p.status + (p.fields.publishAt ? ', ' + niceDay(p.fields.publishAt) : '') + ')';
    if (!who) unassigned.push(entry);
    else (people[who] = people[who] || []).push(entry);
  });
  spinoffs.forEach(function (s) {
    if (s.status === 'published' || !s.fields.assignee) return;
    (people[s.fields.assignee] = people[s.fields.assignee] || []).push(s.fields.title + ' (' + s.id + ', ' + s.status + (s.fields.publishAt ? ', ' + niceDay(s.fields.publishAt) : '') + ')');
  });
  var names = Object.keys(people).sort(function (a, b) { return people[b].length - people[a].length || a.localeCompare(b); });
  parts.push(
    names.length || unassigned.length
      ? 'Who has what, most first: ' + names.map(function (n) { return n + ' ' + people[n].length + ': ' + people[n].join(', '); }).join(' | ') +
        (unassigned.length ? (names.length ? ' | ' : '') + 'unassigned ' + unassigned.length + ': ' + unassigned.join(', ') : '') + '.'
      : 'Nobody has open work.',
  );
  var shown = pieces
    .filter(function (p) {
      return p.status === 'published' || spinoffs.some(function (s) { return s.fields.pieceId === p.id; });
    })
    .sort(function (a, b) { return String(dateOf(b)).localeCompare(String(dateOf(a))); })
    .slice(0, 8);
  parts.push(
    shown.length
      ? 'Repurposing, newest first: ' + shown.map(function (p) {
          var mine = spinoffs.filter(function (s) { return s.fields.pieceId === p.id; });
          return p.fields.title + ' (' + p.id + ', ' + (p.status === 'published' ? 'published ' + (dateOf(p) ? niceDay(dateOf(p)) : '') : 'in ' + p.status) + '): ' +
            (mine.length ? spinoffSummary(mine) : 'nothing repurposed yet');
        }).join(' | ') + '.'
      : 'Nothing published or repurposed yet.',
  );
  var published = pieces.filter(function (p) { return p.status === 'published'; });
  return {
    inPipeline: open.length,
    dueSoon: soon.length,
    late: late.length,
    repurposed: published.filter(function (p) { return spinoffs.some(function (s) { return s.fields.pieceId === p.id; }); }).length,
    summary: parts.join(' '),
  };
}
// ── content-rules-end ──

const pieces = rosterStore(gezel.fs, 'pieces.json', {
  stages: ['idea', 'brief', 'draft', 'edit', 'design', 'published'],
  idPrefix: 'pc',
});
const calendar = rosterStore(gezel.fs, 'calendar.json', {
  stages: ['planned', 'drafted', 'scheduled', 'published'],
  idPrefix: 'so',
});

async function resolveIn(store: typeof pieces, noun: string, example: string) {
  const all = await store.list();
  const keys = [input.id, input.title].filter((k): k is string => typeof k === 'string' && k.trim() !== '');
  for (const key of keys) {
    const found = findRecord(all, key);
    if (found.record) return found.record;
    if (found.matches.length > 1) {
      throw new Error(
        'More than one ' + noun + " matches '" + key + "': " + found.matches.map((r) => r.id + ' ' + String(r.fields.title)).join(', ') + '. Pass id.',
      );
    }
  }
  const known = all.map((r) => r.id + ' ' + String(r.fields.title)).join(', ') || 'none yet';
  throw new Error(
    (keys.length ? 'No ' + noun + " matches '" + keys.join("' or '") + "'. " : "Pass 'id' (e.g. '" + example + "') or the " + noun + "'s 'title'. ") + 'Known: ' + known + '.',
  );
}

const now = Date.now();
const today = localDay(now);
const withinDays = typeof input.withinDays === 'number' && input.withinDays > 0 ? Math.round(input.withinDays) : 14;

function dateInput(value: string | undefined, label: string): string | null {
  if (value === undefined || String(value).trim() === '') return null;
  const day = normalizeDate(value, now);
  if (!day) throw new Error(label + " must be a date, e.g. '2026-12-01'.");
  return day;
}
function shifted(from: unknown, title: unknown): string | null {
  if (typeof input.shiftDays !== 'number' || input.shiftDays === 0) return null;
  if (typeof from !== 'string' || !from) throw new Error(String(title) + ' has no date yet; pass publishAt instead of shiftDays.');
  return addDays(from, Math.round(input.shiftDays));
}

let note = '';

if (input.action === 'add_piece') {
  if (!input.title || !input.title.trim()) throw new Error("add_piece needs 'title'.");
  const publishAt = dateInput(input.publishAt, 'publishAt');
  const format = input.format ? String(input.format).toLowerCase() : undefined;
  if (format && !FORMATS.includes(format)) throw new Error('format must be one of ' + FORMATS.join(', ') + '.');
  const status = input.status ? String(input.status).toLowerCase() : undefined;
  if (status && !STAGES.includes(status)) throw new Error('status must be one of ' + STAGES.join(', ') + '.');
  const wanted = input.title.trim().toLowerCase();
  const existing = (await pieces.list()).find((r) => String(r.fields.title ?? '').toLowerCase() === wanted);
  const wordTarget = wholeNumber(input.words);
  const fields: Record<string, unknown> = {
    ...(format ? { format } : {}),
    ...(publishAt ? { publishAt } : {}),
    ...(input.assignee ? { assignee: input.assignee.trim() } : {}),
    ...(input.keyword ? { keyword: input.keyword.trim() } : {}),
    ...(input.angle ? { angle: input.angle.trim() } : {}),
    ...(wordTarget ? { words: wordTarget } : {}),
    ...(input.link ? { link: input.link.trim() } : {}),
    ...(input.note ? { notes: input.note.trim() } : {}),
    ...(status === 'published' ? { publishedAt: publishAt ?? today } : {}),
  };
  if (existing) {
    await pieces.update(existing.id, { fields });
    if (status && status !== existing.status) await pieces.transition(existing.id, status, { note: 'Updated from the plan' });
    note = 'Updated ' + String(existing.fields.title) + ' (' + existing.id + ').';
  } else {
    const record = await pieces.add({
      status: status ?? 'idea',
      fields: { title: input.title.trim(), format: format ?? 'article', ...fields },
    });
    note = 'Added ' + record.id + ' ' + String(record.fields.title) + ' as ' + record.status + (publishAt ? ', publishing ' + niceDay(publishAt) : '') + '.';
  }
} else if (input.action === 'update_piece') {
  const record = await resolveIn(pieces, 'piece', 'pc-3');
  const fields: Record<string, unknown> = {};
  const publishAt = dateInput(input.publishAt, 'publishAt') ?? shifted(record.fields.publishAt, record.fields.title);
  if (publishAt) fields.publishAt = publishAt;
  if (input.assignee) fields.assignee = input.assignee.trim();
  if (input.keyword) fields.keyword = input.keyword.trim();
  if (input.angle) fields.angle = input.angle.trim();
  if (input.link) fields.link = input.link.trim();
  const wordTarget = wholeNumber(input.words);
  if (wordTarget) fields.words = wordTarget;
  const format = input.format ? String(input.format).toLowerCase() : undefined;
  if (format) {
    if (!FORMATS.includes(format)) throw new Error('format must be one of ' + FORMATS.join(', ') + '.');
    fields.format = format;
  }
  const status = input.status ? String(input.status).toLowerCase() : undefined;
  if (status && !STAGES.includes(status)) throw new Error('status must be one of ' + STAGES.join(', ') + '.');
  if (status === 'published' && record.status !== 'published') fields.publishedAt = today;
  if (!Object.keys(fields).length && !status && !input.note) {
    throw new Error('update_piece needs status, assignee, publishAt, shiftDays, keyword, angle, link, words, format, or note.');
  }
  if (Object.keys(fields).length) await pieces.update(record.id, { fields });
  if (status && status !== record.status) await pieces.transition(record.id, status, input.note ? { note: input.note } : {});
  else if (input.note) await pieces.update(record.id, { note: input.note });
  note =
    String(record.fields.title) + ' (' + record.id + ')' +
    (status && status !== record.status ? ' moved from ' + record.status + ' to ' + status : ' updated') +
    (fields.publishAt ? ', publishing ' + niceDay(String(fields.publishAt)) : '') +
    (fields.assignee ? ', now with ' + String(fields.assignee) : '') + '.';
} else if (input.action === 'repurpose_piece') {
  const piece = await resolveIn(pieces, 'piece', 'pc-3');
  const format = spinFormat(input.format);
  if (!format) throw new Error('repurpose_piece needs format: ' + SPIN_FORMATS.join(', ') + '.');
  const want = Math.min(10, wholeNumber(input.count) || 1);
  const already = (await calendar.list()).filter((s) => s.fields.pieceId === piece.id && s.fields.format === format);
  const missing = want - already.length;
  const nouns = SPIN_NOUN[format] as string[];
  if (missing <= 0) {
    note =
      String(piece.fields.title) + ' (' + piece.id + ') already has ' + already.length + ' ' + (already.length === 1 ? nouns[0] : nouns[1]) +
      '; nothing added. Pass a higher count for more.';
  } else {
    const startAt = dateInput(input.startAt, 'startAt');
    const dates = spinoffDates(piece, format, already.length, missing, startAt, now) as string[];
    const angles = String(input.angle ?? '').split(/\s*\|\s*|\n+/).map((a) => a.trim()).filter(Boolean);
    const added: string[] = [];
    for (let i = 0; i < missing; i++) {
      const index = already.length + i;
      const record = await calendar.add({
        status: 'planned',
        fields: {
          title: spinoffTitle(format, index, Math.max(want, index + 1), String(piece.fields.title)),
          pieceId: piece.id,
          format,
          publishAt: dates[i],
          ...(input.channel ? { channel: input.channel.trim() } : {}),
          ...(input.assignee || piece.fields.assignee ? { assignee: (input.assignee ?? String(piece.fields.assignee)).trim() } : {}),
          ...(angles[i] ? { angle: angles[i] } : {}),
        },
      });
      added.push(record.id + ' ' + niceDay(dates[i]!));
    }
    note =
      'Planned ' + missing + ' ' + (missing === 1 ? nouns[0] : nouns[1]) + ' for ' + String(piece.fields.title) + ' (' + piece.id + '): ' + added.join(', ') + '.';
  }
} else if (input.action === 'update_spinoff') {
  const record = await resolveIn(calendar, 'spin-off', 'so-2');
  const fields: Record<string, unknown> = {};
  const publishAt = dateInput(input.publishAt, 'publishAt') ?? shifted(record.fields.publishAt, record.fields.title);
  if (publishAt) fields.publishAt = publishAt;
  if (input.channel) fields.channel = input.channel.trim();
  if (input.assignee) fields.assignee = input.assignee.trim();
  if (input.angle) fields.angle = input.angle.trim();
  if (input.link) fields.link = input.link.trim();
  const status = input.status ? String(input.status).toLowerCase() : undefined;
  if (status && !SPIN_STAGES.includes(status)) throw new Error('status must be one of ' + SPIN_STAGES.join(', ') + '.');
  if (!Object.keys(fields).length && !status && !input.note) {
    throw new Error('update_spinoff needs status, publishAt, shiftDays, channel, assignee, angle, link, or note.');
  }
  if (Object.keys(fields).length) await calendar.update(record.id, { fields });
  if (status && status !== record.status) await calendar.transition(record.id, status, input.note ? { note: input.note } : {});
  else if (input.note) await calendar.update(record.id, { note: input.note });
  note =
    String(record.fields.title) + ' (' + record.id + ')' +
    (status && status !== record.status ? ' moved from ' + record.status + ' to ' + status : ' updated') +
    (fields.publishAt ? ', going out ' + niceDay(String(fields.publishAt)) : '') + '.';
} else if (input.action !== 'status' && input.action !== 'list') {
  throw new Error(
    "Unknown action '" + input.action + "'. Use status, add_piece, update_piece, repurpose_piece, update_spinoff, or list.",
  );
}

const allPieces = await pieces.list();
const allSpinoffs = await calendar.list();
const view = studioPicture(allPieces, allSpinoffs, now, withinDays);

gezel.output({
  inPipeline: view.inPipeline,
  dueSoon: view.dueSoon,
  late: view.late,
  repurposed: view.repurposed,
  summary:
    input.action === 'list'
      ? [
          ...allPieces.map((p) => '[' + p.status + '] ' + pieceLine(p, now)),
          ...allSpinoffs.map((s) => '  [' + s.status + '] ' + spinoffLine(s, allPieces, now)),
        ].join('\n') || 'The studio is empty.'
      : (note ? note + ' ' : '') + view.summary,
});

